// Package workitems contains the fail-closed suggestion contract and the
// transactional mutation executor for Goals/Milestones state.
package workitems

import (
	"encoding/json"
	"fmt"
	"strings"
)

// Actions the AI may suggest. Each maps to one mutation in apply.go.
const (
	ActionCreate        = "create"
	ActionUpdate        = "update"
	ActionSetStatus     = "set_status"
	ActionSetImportance = "set_importance"
	ActionSetActive     = "set_active"
	ActionClearActive   = "clear_active"
	ActionMove          = "move"
	ActionIndent        = "indent"
	ActionOutdent       = "outdent"
)

var validActions = map[string]bool{
	ActionCreate: true, ActionUpdate: true, ActionSetStatus: true,
	ActionSetImportance: true, ActionSetActive: true, ActionClearActive: true,
	ActionMove: true, ActionIndent: true, ActionOutdent: true,
}

var validKinds = map[string]bool{"goal": true, "milestone": true}

var validStatuses = map[string]bool{
	"planned": true, "in_progress": true, "on_hold": true,
	"completed": true, "deferred": true, "cancelled": true,
}

// Suggestion is the AI's proposed work-item mutation, as submitted.
type Suggestion struct {
	SessionID string
	Directory string
	ItemID    *int64
	Action    string
	Payload   json.RawMessage
	Rationale string
}

// Mutation is the validated, normalized form the executor runs. It is also
// the JSON stored in work_item_suggestions.payload.
type Mutation struct {
	Action      string
	ItemID      *int64
	Directory   string
	Kind        string
	Name        string
	Description string
	ParentID    *int64
	Status      string
	Reason      string
	Importance  int64
	Delta       int
}

// ParseMutation validates a suggestion's shape and normalizes its payload.
// It performs no writes and no existence checks (the caller checks item
// existence against the store before the suggestion enters the queue).
func ParseMutation(s Suggestion) (Mutation, error) {
	dir := strings.TrimSpace(s.Directory)
	if dir == "" {
		return Mutation{}, fmt.Errorf("[manage] work-item suggestion needs a directory")
	}
	if !validActions[s.Action] {
		return Mutation{}, fmt.Errorf("[manage] unknown work-item action %q", s.Action)
	}

	m := Mutation{Action: s.Action, ItemID: s.ItemID, Directory: dir}

	// create and clear_active carry no item_id; every other action targets one.
	if s.Action != ActionCreate && s.Action != ActionClearActive && s.ItemID == nil {
		return Mutation{}, fmt.Errorf("[manage] work-item action %q needs an item_id", s.Action)
	}

	var payload map[string]any
	if len(s.Payload) > 0 {
		if err := json.Unmarshal(s.Payload, &payload); err != nil {
			return Mutation{}, fmt.Errorf("[manage] work-item suggestion payload is not valid JSON: %w", err)
		}
	}

	switch s.Action {
	case ActionCreate:
		kind, _ := payload["kind"].(string)
		if !validKinds[kind] {
			return Mutation{}, fmt.Errorf("[manage] work-item create needs kind goal or milestone")
		}
		name := strings.TrimSpace(payload["name"].(string))
		if name == "" {
			return Mutation{}, fmt.Errorf("[manage] work-item create needs a non-empty name")
		}
		m.Kind = kind
		m.Name = name
		m.Description, _ = payload["description"].(string)
		if pid, ok := payload["parent_id"]; ok && pid != nil {
			f, ok := pid.(float64)
			if !ok {
				return Mutation{}, fmt.Errorf("[manage] work-item create parent_id must be a number")
			}
			v := int64(f)
			m.ParentID = &v
		}
	case ActionUpdate:
		name := strings.TrimSpace(payload["name"].(string))
		if name == "" {
			return Mutation{}, fmt.Errorf("[manage] work-item update needs a non-empty name")
		}
		m.Name = name
		m.Description, _ = payload["description"].(string)
	case ActionSetStatus:
		status, _ := payload["status"].(string)
		if !validStatuses[status] {
			return Mutation{}, fmt.Errorf("[manage] invalid work-item status %q", status)
		}
		m.Status = status
		m.Reason, _ = payload["reason"].(string)
	case ActionSetImportance:
		imp, ok := payload["importance"].(float64)
		if !ok {
			m.Importance = 3
		} else {
			m.Importance = clampImportance(int64(imp))
		}
	case ActionMove:
		delta, _ := payload["delta"].(float64)
		if delta < 0 {
			m.Delta = -1
		} else {
			m.Delta = 1
		}
	}
	return m, nil
}

func clampImportance(v int64) int64 {
	if v < 1 {
		return 1
	}
	if v > 5 {
		return 5
	}
	return v
}

