// Transactional mutation executor. Ports the sibling-order semantics of the
// provisional Lua adapter (goals.lua M.*) onto the sqlc store.
package workitems

import (
	"context"
	"database/sql"
	"errors"
	"fmt"

	"github.com/alterejoe/opencode-manage/internal/store"
)

// Apply runs one validated mutation inside the caller's transaction and
// records the corresponding work_item_event. It returns the affected item
// id (the new id for create). The caller owns the transaction lifecycle.
func Apply(ctx context.Context, q *store.Queries, m Mutation, actor, sessionID string) (int64, error) {
	switch m.Action {
	case ActionCreate:
		return applyCreate(ctx, q, m, actor, sessionID)
	case ActionUpdate:
		return applyUpdate(ctx, q, m, actor, sessionID)
	case ActionSetStatus:
		return applySetStatus(ctx, q, m, actor, sessionID)
	case ActionSetImportance:
		return applySetImportance(ctx, q, m, actor, sessionID)
	case ActionSetActive:
		return applySetActive(ctx, q, m, actor, sessionID)
	case ActionClearActive:
		return applyClearActive(ctx, q, m, actor, sessionID)
	case ActionMove:
		return applyMove(ctx, q, m, actor, sessionID)
	case ActionIndent:
		return applyIndent(ctx, q, m, actor, sessionID)
	case ActionOutdent:
		return applyOutdent(ctx, q, m, actor, sessionID)
	}
	return 0, fmt.Errorf("[manage] unknown work-item action %q", m.Action)
}

func recordEvent(ctx context.Context, q *store.Queries, directory string, itemID int64, actor, sessionID, eventType, reason string) error {
	return q.InsertWorkItemEvent(ctx, store.InsertWorkItemEventParams{
		Directory: directory,
		ItemID:    itemID,
		Actor:     actor,
		EventType: eventType,
		Reason:    reason,
		SessionID: sessionID,
	})
}

func applyCreate(ctx context.Context, q *store.Queries, m Mutation, actor, sessionID string) (int64, error) {
	siblings, err := q.ListSiblings(ctx, store.ListSiblingsParams{Directory: m.Directory, ParentID: m.ParentID})
	if err != nil {
		return 0, err
	}
	item, err := q.InsertWorkItem(ctx, store.InsertWorkItemParams{
		Directory:    m.Directory,
		ParentID:     m.ParentID,
		Kind:         m.Kind,
		Name:         m.Name,
		Description:  m.Description,
		Importance:   3,
		SiblingOrder: int64(len(siblings)),
	})
	if err != nil {
		return 0, err
	}
	if err := recordEvent(ctx, q, m.Directory, item.ID, actor, sessionID, "created", m.Kind+": "+m.Name); err != nil {
		return 0, err
	}
	return item.ID, nil
}

func applyUpdate(ctx context.Context, q *store.Queries, m Mutation, actor, sessionID string) (int64, error) {
	if err := q.UpdateWorkItem(ctx, store.UpdateWorkItemParams{
		Name:        m.Name,
		Description: m.Description,
		ID:          *m.ItemID,
		Directory:   m.Directory,
	}); err != nil {
		return 0, err
	}
	if err := recordEvent(ctx, q, m.Directory, *m.ItemID, actor, sessionID, "edited", m.Name); err != nil {
		return 0, err
	}
	return *m.ItemID, nil
}

func applySetStatus(ctx context.Context, q *store.Queries, m Mutation, actor, sessionID string) (int64, error) {
	if err := q.SetWorkItemStatus(ctx, store.SetWorkItemStatusParams{
		Status:     m.Status,
		HoldReason: m.Reason,
		ID:         *m.ItemID,
		Directory:  m.Directory,
	}); err != nil {
		return 0, err
	}
	reason := m.Status
	if m.Reason != "" {
		reason += ": " + m.Reason
	}
	if err := recordEvent(ctx, q, m.Directory, *m.ItemID, actor, sessionID, "status", reason); err != nil {
		return 0, err
	}
	return *m.ItemID, nil
}

func applySetImportance(ctx context.Context, q *store.Queries, m Mutation, actor, sessionID string) (int64, error) {
	if err := q.SetWorkItemImportance(ctx, store.SetWorkItemImportanceParams{
		Importance: m.Importance,
		ID:         *m.ItemID,
		Directory:  m.Directory,
	}); err != nil {
		return 0, err
	}
	if err := recordEvent(ctx, q, m.Directory, *m.ItemID, actor, sessionID, "importance", fmt.Sprintf("%d", m.Importance)); err != nil {
		return 0, err
	}
	return *m.ItemID, nil
}

func applySetActive(ctx context.Context, q *store.Queries, m Mutation, actor, sessionID string) (int64, error) {
	if _, err := q.GetWorkItem(ctx, store.GetWorkItemParams{ID: *m.ItemID, Directory: m.Directory}); err != nil {
		return 0, fmt.Errorf("[manage] work item not found: %w", err)
	}
	if err := q.UpsertActiveWorkItem(ctx, store.UpsertActiveWorkItemParams{Directory: m.Directory, ItemID: *m.ItemID}); err != nil {
		return 0, err
	}
	if err := recordEvent(ctx, q, m.Directory, *m.ItemID, actor, sessionID, "activated", ""); err != nil {
		return 0, err
	}
	return *m.ItemID, nil
}

func applyClearActive(ctx context.Context, q *store.Queries, m Mutation, actor, sessionID string) (int64, error) {
	active, err := q.GetActiveWorkItem(ctx, m.Directory)
	if err != nil && !errors.Is(err, sql.ErrNoRows) {
		return 0, err
	}
	if err := q.ClearActiveWorkItem(ctx, m.Directory); err != nil {
		return 0, err
	}
	if err == nil {
		if err := recordEvent(ctx, q, m.Directory, active.ItemID, actor, sessionID, "deactivated", ""); err != nil {
			return 0, err
		}
		return active.ItemID, nil
	}
	return 0, nil
}

func applyMove(ctx context.Context, q *store.Queries, m Mutation, actor, sessionID string) (int64, error) {
	item, err := q.GetWorkItem(ctx, store.GetWorkItemParams{ID: *m.ItemID, Directory: m.Directory})
	if err != nil {
		return 0, fmt.Errorf("[manage] work item not found: %w", err)
	}
	rows, err := q.ListSiblings(ctx, store.ListSiblingsParams{Directory: m.Directory, ParentID: item.ParentID})
	if err != nil {
		return 0, err
	}
	index := -1
	for i, r := range rows {
		if r.ID == item.ID {
			index = i
			break
		}
	}
	if index < 0 {
		return 0, fmt.Errorf("[manage] work item is not ordered")
	}
	target := index + m.Delta
	if target < 0 || target >= len(rows) {
		return item.ID, nil // boundary no-op, matching the Lua adapter
	}
	rows[index], rows[target] = rows[target], rows[index]
	for i, r := range rows {
		if err := q.SetSiblingOrder(ctx, store.SetSiblingOrderParams{
			SiblingOrder: int64(i),
			ID:           r.ID,
			Directory:    m.Directory,
		}); err != nil {
			return 0, err
		}
	}
	if err := recordEvent(ctx, q, m.Directory, item.ID, actor, sessionID, "reordered", fmt.Sprintf("%d", m.Delta)); err != nil {
		return 0, err
	}
	return item.ID, nil
}

func applyIndent(ctx context.Context, q *store.Queries, m Mutation, actor, sessionID string) (int64, error) {
	item, err := q.GetWorkItem(ctx, store.GetWorkItemParams{ID: *m.ItemID, Directory: m.Directory})
	if err != nil {
		return 0, fmt.Errorf("[manage] work item not found: %w", err)
	}
	rows, err := q.ListSiblings(ctx, store.ListSiblingsParams{Directory: m.Directory, ParentID: item.ParentID})
	if err != nil {
		return 0, err
	}
	index := -1
	for i, r := range rows {
		if r.ID == item.ID {
			index = i
			break
		}
	}
	if index <= 0 {
		return item.ID, nil // no previous sibling: no-op
	}
	previous := rows[index-1]
	childRows, err := q.ListSiblings(ctx, store.ListSiblingsParams{Directory: m.Directory, ParentID: &previous.ID})
	if err != nil {
		return 0, err
	}
	if err := q.SetWorkItemParentOrder(ctx, store.SetWorkItemParentOrderParams{
		ParentID:     &previous.ID,
		SiblingOrder: int64(len(childRows)),
		ID:           item.ID,
		Directory:    m.Directory,
	}); err != nil {
		return 0, err
	}
	if err := recordEvent(ctx, q, m.Directory, item.ID, actor, sessionID, "indented", fmt.Sprintf("%d", previous.ID)); err != nil {
		return 0, err
	}
	return item.ID, nil
}

func applyOutdent(ctx context.Context, q *store.Queries, m Mutation, actor, sessionID string) (int64, error) {
	item, err := q.GetWorkItem(ctx, store.GetWorkItemParams{ID: *m.ItemID, Directory: m.Directory})
	if err != nil {
		return 0, fmt.Errorf("[manage] work item not found: %w", err)
	}
	if item.ParentID == nil {
		return item.ID, nil // already at root: no-op
	}
	parent, err := q.GetWorkItem(ctx, store.GetWorkItemParams{ID: *item.ParentID, Directory: m.Directory})
	if err != nil {
		return 0, fmt.Errorf("[manage] parent work item not found: %w", err)
	}
	newParent := parent.ParentID
	newOrder := parent.SiblingOrder + 1
	if err := q.ShiftSiblingOrders(ctx, store.ShiftSiblingOrdersParams{
		Directory: m.Directory,
		ParentID:  newParent,
		MinOrder:  newOrder,
	}); err != nil {
		return 0, err
	}
	if err := q.SetWorkItemParentOrder(ctx, store.SetWorkItemParentOrderParams{
		ParentID:     newParent,
		SiblingOrder: newOrder,
		ID:           item.ID,
		Directory:    m.Directory,
	}); err != nil {
		return 0, err
	}
	detail := "root"
	if newParent != nil {
		detail = fmt.Sprintf("%d", *newParent)
	}
	if err := recordEvent(ctx, q, m.Directory, item.ID, actor, sessionID, "outdented", detail); err != nil {
		return 0, err
	}
	return item.ID, nil
}

