// mountWorkItems registers the work-item routes. The event recorder
// middleware (mounted in Mount) covers them like every other /v1/* path.
func mountWorkItems(r chi.Router, db *sql.DB) {
	q := store.New(db)

	r.Get("/v1/work-items", func(w http.ResponseWriter, r *http.Request) {
		directory := r.URL.Query().Get("directory")
		if directory == "" {
			fail(w, http.StatusUnprocessableEntity, "[manage] work-items list needs a directory")
			return
		}
		items, err := q.ListWorkItems(r.Context(), directory)
		if err != nil {
			fail(w, http.StatusInternalServerError, "[manage] work-items list failed: "+err.Error())
			return
		}
		activeID, err := activeWorkItemID(r.Context(), q, directory)
		if err != nil {
			fail(w, http.StatusInternalServerError, "[manage] active work item lookup failed: "+err.Error())
			return
		}
		writeJSON(w, http.StatusOK, map[string]any{"items": items, "active_id": activeID})
	})

	r.Get("/v1/work-items/context", func(w http.ResponseWriter, r *http.Request) {
		directory := r.URL.Query().Get("directory")
		itemID, err := strconv.ParseInt(r.URL.Query().Get("item_id"), 10, 64)
		if directory == "" || err != nil {
			fail(w, http.StatusUnprocessableEntity, "[manage] work-items context needs directory and item_id")
			return
		}
		item, err := q.GetWorkItem(r.Context(), store.GetWorkItemParams{ID: itemID, Directory: directory})
		if err != nil {
			fail(w, http.StatusNotFound, "[manage] work item not found: "+err.Error())
			return
		}
		ancestors, err := workItemAncestors(r.Context(), q, directory, item.ParentID)
		if err != nil {
			fail(w, http.StatusInternalServerError, "[manage] ancestors lookup failed: "+err.Error())
			return
		}
		children, err := q.ListSiblings(r.Context(), store.ListSiblingsParams{Directory: directory, ParentID: &itemID})
		if err != nil {
			fail(w, http.StatusInternalServerError, "[manage] children lookup failed: "+err.Error())
			return
		}
		events, err := q.ListWorkItemEvents(r.Context(), store.ListWorkItemEventsParams{Directory: directory, ItemID: itemID})
		if err != nil {
			fail(w, http.StatusInternalServerError, "[manage] events lookup failed: "+err.Error())
			return
		}
		writeJSON(w, http.StatusOK, map[string]any{
			"item": item, "ancestors": ancestors, "children": children, "events": events,
		})
	})

	r.Post("/v1/work-items/suggest", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Directory string          `json:"directory"`
			SessionID string          `json:"session_id"`
			ItemID    *int64          `json:"item_id"`
			Action    string          `json:"action"`
			Payload   json.RawMessage `json:"payload"`
			Rationale string          `json:"rationale"`
		}
		if !decode(w, r, &req) {
			return
		}
		m, err := workitems.ParseMutation(workitems.Suggestion{
			SessionID: req.SessionID,
			Directory: req.Directory,
			ItemID:    req.ItemID,
			Action:    req.Action,
			Payload:   req.Payload,
			Rationale: req.Rationale,
		})
		if err != nil {
			fail(w, http.StatusUnprocessableEntity, err.Error())
			return
		}
		// Fail-closed: a mutation targeting a missing item never enters the
		// queue (create and clear_active carry no item).
		if m.ItemID != nil {
			if _, err := q.GetWorkItem(r.Context(), store.GetWorkItemParams{ID: *m.ItemID, Directory: m.Directory}); err != nil {
				fail(w, http.StatusUnprocessableEntity, "[manage] work-item suggestion targets a missing item: "+err.Error())
				return
			}
		}
		payloadJSON, err := json.Marshal(m)
		if err != nil {
			fail(w, http.StatusInternalServerError, "[manage] could not encode suggestion payload: "+err.Error())
			return
		}
		suggestion, err := q.AppendSuggestion(r.Context(), store.AppendSuggestionParams{
			SessionID: req.SessionID,
			Directory: m.Directory,
			ItemID:    m.ItemID,
			Action:    m.Action,
			Payload:   string(payloadJSON),
			Rationale: req.Rationale,
		})
		if err != nil {
			fail(w, http.StatusInternalServerError, "[manage] could not append suggestion: "+err.Error())
			return
		}
		writeJSON(w, http.StatusOK, suggestion)
	})

	r.Get("/v1/work-items/suggestions", func(w http.ResponseWriter, r *http.Request) {
		directory := r.URL.Query().Get("directory")
		status := r.URL.Query().Get("status")
		if status == "" {
			status = "pending"
		}
		if directory == "" {
			fail(w, http.StatusUnprocessableEntity, "[manage] suggestions list needs a directory")
			return
		}
		rows, err := q.ListSuggestions(r.Context(), store.ListSuggestionsParams{Directory: directory, Status: status})
		if err != nil {
			fail(w, http.StatusInternalServerError, "[manage] suggestions list failed: "+err.Error())
			return
		}
		writeJSON(w, http.StatusOK, rows)
	})

	r.Post("/v1/work-items/suggestions/{id}/apply", func(w http.ResponseWriter, r *http.Request) {
		resolveSuggestion(w, r, q, db, "applied")
	})

	r.Post("/v1/work-items/suggestions/{id}/reject", func(w http.ResponseWriter, r *http.Request) {
		resolveSuggestion(w, r, q, db, "rejected")
	})
}

// resolveSuggestion applies or rejects one pending suggestion. Apply runs
// the stored mutation and marks the suggestion applied in the same
// transaction; reject only flips the status.
func resolveSuggestion(w http.ResponseWriter, r *http.Request, q *store.Queries, db *sql.DB, outcome string) {
	id, err := strconv.ParseInt(chi.URLParam(r, "id"), 10, 64)
	if err != nil {
		fail(w, http.StatusUnprocessableEntity, "[manage] suggestion id must be a number")
		return
	}
	var req struct {
		Directory string `json:"directory"`
		SessionID string `json:"session_id"`
	}
	if !decode(w, r, &req) {
		return
	}
	suggestion, err := q.GetSuggestion(r.Context(), store.GetSuggestionParams{ID: id, Directory: req.Directory})
	if err != nil {
		fail(w, http.StatusNotFound, "[manage] suggestion not found: "+err.Error())
		return
	}
	if suggestion.Status != "pending" {
		fail(w, http.StatusConflict, "[manage] suggestion is already "+suggestion.Status)
		return
	}

	if outcome == "applied" {
		var m workitems.Mutation
		if err := json.Unmarshal([]byte(suggestion.Payload), &m); err != nil {
			fail(w, http.StatusInternalServerError, "[manage] stored suggestion payload is corrupt: "+err.Error())
			return
		}
		tx, err := db.BeginTx(r.Context(), nil)
		if err != nil {
			fail(w, http.StatusInternalServerError, "[manage] could not begin transaction: "+err.Error())
			return
		}
		defer tx.Rollback()
		qtx := q.WithTx(tx)
		if _, err := workitems.Apply(r.Context(), qtx, m, "user", req.SessionID); err != nil {
			fail(w, http.StatusUnprocessableEntity, "[manage] suggestion apply failed: "+err.Error())
			return
		}
		if err := qtx.SetSuggestionStatus(r.Context(), store.SetSuggestionStatusParams{
			Status:    "applied",
			AppliedBy: "user",
			ID:        suggestion.ID,
			Directory: req.Directory,
		}); err != nil {
			fail(w, http.StatusInternalServerError, "[manage] could not mark suggestion applied: "+err.Error())
			return
		}
		if err := tx.Commit(); err != nil {
			fail(w, http.StatusInternalServerError, "[manage] could not commit: "+err.Error())
			return
		}
	} else {
		if err := q.SetSuggestionStatus(r.Context(), store.SetSuggestionStatusParams{
			Status:    "rejected",
			AppliedBy: "user",
			ID:        suggestion.ID,
			Directory: req.Directory,
		}); err != nil {
			fail(w, http.StatusInternalServerError, "[manage] could not mark suggestion rejected: "+err.Error())
			return
		}
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true, "status": outcome})
}

func activeWorkItemID(ctx context.Context, q *store.Queries, directory string) (*int64, error) {
	active, err := q.GetActiveWorkItem(ctx, directory)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, nil
		}
		return nil, err
	}
	return &active.ItemID, nil
}

func workItemAncestors(ctx context.Context, q *store.Queries, directory string, parentID *int64) ([]store.WorkItem, error) {
	var out []store.WorkItem
	for parentID != nil {
		parent, err := q.GetWorkItem(ctx, store.GetWorkItemParams{ID: *parentID, Directory: directory})
		if err != nil {
			return nil, err
		}
		out = append([]store.WorkItem{parent}, out...)
		parentID = parent.ParentID
	}
	return out, nil
}

